package com.fuelflex.platform.operations.repository;import java.math.BigDecimal;import java.util.*;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;import com.fuelflex.platform.operations.entity.InternalConsumptionStockMovement;
